CREATE FUNCTION c1_api.support_review(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;h c1_private.catalog_head;t c1_private.terms;st c1_private.stores;b c1_private.payer_bindings;p jsonb;qty int;BEGIN d=c1_private.guard(n,true);s=c1_private.auth(n,q,true);SELECT * INTO b FROM c1_private.payer_bindings WHERE ns=n AND subject=s.subject AND enabled;IF NOT FOUND THEN PERFORM c1_private.fail('PAYER_REQUIRED');END IF;SELECT * INTO st FROM c1_private.stores WHERE ns=n AND store=q->>'store';SELECT * INTO h FROM c1_private.catalog_head WHERE ns=n AND store=st.store AND meal=q->>'meal';IF NOT FOUND OR NOT h.listed OR st.closed OR st.paused THEN PERFORM c1_private.fail('UNAVAILABLE');END IF;SELECT * INTO t FROM c1_private.terms WHERE ns=n AND store=h.store AND meal=h.meal AND version=h.version;qty=(q->>'quantity')::int;IF qty NOT BETWEEN 1 AND 10 OR st.lifetime+qty>10 OR NOT c1_private.content_available(n,t.store,t.meal,t.version) THEN PERFORM c1_private.fail('CAP_OR_CONTENT');END IF;p=jsonb_build_object('store',st.store,'meal',h.meal,'version',h.version,'terms_hash','0x'||encode(t.terms_hash,'hex'),'quantity',qty,'unit_price',t.price::text,'amount',(t.price*qty)::text,'payer',b.address,'payer_revision',b.revision,'control_revision',st.control_revision);INSERT INTO c1_private.reviews VALUES(n,(q->>'review_id')::uuid,s.subject,'fund',p,d.now+300);RETURN jsonb_build_object('reviewId',q->>'review_id','terms',c1_private.term_dto(n,t.store,t.meal,t.version),'quantity',qty,'amount',(t.price*qty)::text,'expiresAt',d.now+300,'provenance',c1_private.provenance(n));END $$;
CREATE FUNCTION c1_api.support_confirm(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;r c1_private.reviews;p jsonb;b c1_private.payer_bindings;st c1_private.stores;old jsonb;res jsonb;k text;BEGIN d=c1_private.guard(n);s=c1_private.auth(n,q,true);SELECT * INTO b FROM c1_private.payer_bindings WHERE ns=n AND subject=s.subject AND enabled;IF NOT FOUND THEN PERFORM c1_private.fail('PAYER_REQUIRED');END IF;old=c1_private.idem(n,s,'fund',q);IF old IS NOT NULL THEN RETURN old;END IF;PERFORM c1_private.guard(n,true);SELECT * INTO r FROM c1_private.reviews WHERE ns=n AND id=(q->'client'->>'reviewId')::uuid AND kind='fund' AND subject=s.subject;IF NOT FOUND OR r.expires<=d.now THEN PERFORM c1_private.fail('STALE_REVIEW');END IF;p=r.payload;SELECT * INTO st FROM c1_private.stores WHERE ns=n AND store=p->>'store';IF st.closed OR st.paused OR st.control_revision<>(p->>'control_revision')::bigint OR b.revision<>(p->>'payer_revision')::bigint OR (SELECT version FROM c1_private.catalog_head WHERE ns=n AND store=st.store AND meal=p->>'meal')<>(p->>'version')::bigint OR (SELECT NOT listed FROM c1_private.catalog_head WHERE ns=n AND store=st.store AND meal=p->>'meal') THEN PERFORM c1_private.fail('CONFLICT');END IF;IF st.lifetime+(p->>'quantity')::int+coalesce((SELECT sum((payload->>'quantity')::int) FROM c1_private.intents WHERE ns=n AND action='fund' AND payload->>'store'=st.store AND stage NOT IN('FINAL_SUCCEEDED','FINAL_REVERT','DEFINITELY_UNEXECUTED')),0)>10 THEN PERFORM c1_private.fail('CAP');END IF;FOREACH k IN ARRAY ARRAY['support_subject:'||s.subject,'support_payer:'||b.address] LOOP INSERT INTO c1_private.gates(ns,kind,key) VALUES(n,'support',k) ON CONFLICT DO NOTHING;IF EXISTS(SELECT 1 FROM c1_private.gates WHERE ns=n AND kind='support' AND key=k AND pending IS NOT NULL) THEN PERFORM c1_private.fail('PENDING');END IF;END LOOP;IF NOT c1_private.content_available(n,st.store,p->>'meal',(p->>'version')::bigint) THEN PERFORM c1_private.fail('CONTENT_UNAVAILABLE');END IF;p=p||jsonb_build_object('deadline',d.now+600,'quote_id',q->>'quote_id','batch_id',q->>'batch_id');res=c1_private.new_intent(n,s,'fund',q,p,true);UPDATE c1_private.gates SET pending=(res->>'id')::uuid WHERE ns=n AND kind='support' AND key IN('support_subject:'||s.subject,'support_payer:'||b.address);RETURN res;END $$;
CREATE FUNCTION c1_api.claim_review(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;u c1_private.units;t c1_private.terms;st c1_private.stores;p jsonb;BEGIN d=c1_private.guard(n,true);s=c1_private.auth(n,q,true);SELECT * INTO st FROM c1_private.stores WHERE ns=n AND store=q->>'store';IF NOT FOUND OR st.closed OR st.paused OR NOT EXISTS(SELECT 1 FROM c1_private.catalog_head WHERE ns=n AND store=st.store AND meal=q->>'meal' AND listed) THEN PERFORM c1_private.fail('UNAVAILABLE');END IF;
 IF EXISTS(SELECT 1 FROM c1_private.units WHERE ns=n AND store=st.store AND bucket='R' AND expires_at<=d.now AND lock_id IS NULL AND marker_id IS NULL AND active_op IS NOT NULL) THEN PERFORM c1_private.fail('PENDING');END IF;
 SELECT * INTO u FROM c1_private.units WHERE ns=n AND store=st.store AND meal=q->>'meal' AND (bucket='A' OR (bucket='R' AND expires_at<=d.now AND lock_id IS NULL AND marker_id IS NULL)) ORDER BY seq LIMIT 1;
 IF NOT FOUND THEN PERFORM c1_private.fail('NO_STOCK');END IF;IF u.active_op IS NOT NULL THEN PERFORM c1_private.fail('PENDING');END IF;SELECT * INTO t FROM c1_private.terms WHERE ns=n AND store=u.store AND meal=u.meal AND version=u.version;IF NOT FOUND OR NOT c1_private.content_available(n,t.store,t.meal,t.version) THEN PERFORM c1_private.fail('CONTENT_UNAVAILABLE');END IF;
 p=jsonb_build_object('store',u.store,'meal',u.meal,'seq',u.seq,'generation',(u.generation+1)::text,'terms_hash','0x'||encode(u.terms_hash,'hex'),'version',u.version,'control_revision',st.control_revision);INSERT INTO c1_private.reviews VALUES(n,(q->>'review_id')::uuid,s.subject,'issue',p,d.now+300);RETURN jsonb_build_object('reviewId',q->>'review_id','candidate',p,'terms',c1_private.term_dto(n,u.store,u.meal,u.version),'expiresAt',d.now+300);END $$;
CREATE FUNCTION c1_api.claim_confirm(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;i c1_private.identities;r c1_private.reviews;u c1_private.units;st c1_private.stores;p jsonb;old jsonb;res jsonb;email text;BEGIN d=c1_private.guard(n);s=c1_private.auth(n,q,true);old=c1_private.idem(n,s,'issue',q);IF old IS NOT NULL THEN RETURN old;END IF;PERFORM c1_private.guard(n,true);SELECT * INTO i FROM c1_private.identities WHERE ns=n AND subject=s.subject;email=encode(i.email_key,'hex');INSERT INTO c1_private.gates(ns,kind,key) VALUES(n,'subject_issue',s.subject),(n,'email',email) ON CONFLICT DO NOTHING;
 IF EXISTS(SELECT 1 FROM c1_private.gates WHERE ns=n AND ((kind='subject_issue' AND key=s.subject) OR (kind='email' AND key=email)) AND (pending IS NOT NULL OR quarantine OR next_eligible>d.now)) THEN PERFORM c1_private.fail('PENDING_OR_COOLDOWN');END IF;
 SELECT * INTO r FROM c1_private.reviews WHERE ns=n AND id=(q->'client'->>'reviewId')::uuid AND subject=s.subject AND kind='issue';IF NOT FOUND OR r.expires<=d.now THEN PERFORM c1_private.fail('STALE_REVIEW');END IF;p=r.payload;SELECT * INTO st FROM c1_private.stores WHERE ns=n AND store=p->>'store';IF st.closed OR st.paused OR st.control_revision<>(p->>'control_revision')::bigint OR NOT EXISTS(SELECT 1 FROM c1_private.catalog_head WHERE ns=n AND store=st.store AND meal=p->>'meal' AND listed) THEN PERFORM c1_private.fail('CONFLICT');END IF;
 IF EXISTS(SELECT 1 FROM c1_private.units WHERE ns=n AND store=st.store AND bucket='R' AND expires_at<=d.now AND lock_id IS NULL AND marker_id IS NULL AND active_op IS NOT NULL) THEN PERFORM c1_private.fail('PENDING');END IF;
 SELECT * INTO u FROM c1_private.units WHERE ns=n AND store=st.store AND meal=p->>'meal' AND (bucket='A' OR (bucket='R' AND expires_at<=d.now AND lock_id IS NULL AND marker_id IS NULL)) ORDER BY seq LIMIT 1;
 IF NOT FOUND OR u.seq<>(p->>'seq')::smallint OR u.generation+1<>(p->>'generation')::numeric OR encode(u.terms_hash,'hex')<>substring(p->>'terms_hash' FROM 3) OR u.active_op IS NOT NULL THEN PERFORM c1_private.fail('CONFLICT');END IF;IF NOT EXISTS(SELECT 1 FROM c1_private.terms WHERE ns=n AND store=u.store AND meal=u.meal AND version=u.version AND c1_private.content_available(n,u.store,u.meal,u.version)) THEN PERFORM c1_private.fail('CONTENT_UNAVAILABLE');END IF;
 p=p||jsonb_build_object('deadline',d.now+300,'issued_email_key',email,'original_subject',s.subject);res=c1_private.new_intent(n,s,'issue',q,p);UPDATE c1_private.units SET active_op=(res->>'id')::uuid WHERE ns=n AND store=u.store AND seq=u.seq;UPDATE c1_private.gates SET pending=(res->>'id')::uuid WHERE ns=n AND ((kind='subject_issue' AND key=s.subject) OR (kind='email' AND key=email));RETURN res;END $$;
CREATE FUNCTION c1_api.my_vouchers(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;e bytea;BEGIN PERFORM c1_private.cursor_guard(n,q);s=c1_private.auth(n,q);SELECT email_key INTO e FROM c1_private.identities WHERE ns=n AND subject=s.subject;RETURN jsonb_build_object('items',(SELECT coalesce(jsonb_agg(c1_private.voucher_dto(n,id)),'[]') FROM (SELECT id FROM c1_private.vouchers WHERE ns=n AND email_key=e AND id>coalesce(q->>'after','') ORDER BY id LIMIT least(coalesce((q->>'limit')::int,20),50)) v),'provenance',c1_private.provenance(n));END $$;
CREATE FUNCTION c1_api.voucher_get(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;v c1_private.vouchers;BEGIN s=c1_private.auth(n,q);v=c1_private.voucher_auth(n,s,q->>'id');RETURN c1_private.voucher_dto(n,v.id);END $$;
